layer.css:
[data-ryt="footer"] { color: var(--ryt-accent); background-color: var(--ryt-header-bg); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 24px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 3px; transition: text-decoration-color 0.2s, -webkit-text-decoration-color 0.2s }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-thickness: 1px; text-underline-offset: 3px; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: text-decoration-color 0.2s, -webkit-text-decoration-color 0.2s }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(169, 9, 64); border-top: 1px solid rgb(169, 9, 64); border-right: 1px solid rgb(169, 9, 64); border-bottom: 1px solid rgb(169, 9, 64); border-left: 1px solid rgb(169, 9, 64); border-radius: 4px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 12px; padding-right: 16px; padding-bottom: 12px; padding-left: 16px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(102, 77, 3); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(102, 77, 3); text-decoration-thickness: 1px; text-underline-offset: 3px; transition: text-decoration-color 0.2s, -webkit-text-decoration-color 0.2s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: color-mix(in srgb, var(--ryt-text) 75%, transparent); font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 75%, transparent); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="cover"] { border-radius: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: text-decoration-color 0.2s, -webkit-text-decoration-color 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: text-decoration-color 0.2s, -webkit-text-decoration-color 0.2s; position: relative }
[data-ryt="rec-card"] [data-ryt="title"]::after { content: ""; display: block; position: absolute; width: 100%; height: 503.688px; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
[data-ryt="button"]:hover { background-color: #900836; color: #fff }
[data-ryt="nav"] a:hover { color: #870733 }
